const previewDialog = $('#previewDialog');
function openGuide(title, html) {
  $('#previewTitle').textContent = title;
  $('#previewBody').innerHTML = `<div class="guide-body">${html}</div>`;
  previewDialog.showModal();
}
$('#previewClose').addEventListener('click', () => previewDialog.close());
previewDialog.addEventListener('click', (event) => { if (event.target === previewDialog) previewDialog.close(); });

const INSTALL_DISMISS_KEY = 'alum-install-dismissed';
// Written when the browser confirms the app got installed, so the install banner stops
// asking on every later visit too (a dismissal is per visit, an installation is not).
const INSTALLED_KEY = 'alum-app-installed';

// The install banner asks again on every visit until the app is really installed:
// sessionStorage is emptied when the tab closes, localStorage is not.
const sessionFlag = (key) => { try { return sessionStorage.getItem(key) === '1'; } catch { return false; } };
const setSessionFlag = (key) => { try { sessionStorage.setItem(key, '1'); } catch { /* private mode */ } };
const clearSessionFlag = (key) => { try { sessionStorage.removeItem(key); } catch { /* private mode */ } };
const localFlag = (key) => { try { return localStorage.getItem(key) === '1'; } catch { return false; } };
const setLocalFlag = (key) => { try { localStorage.setItem(key, '1'); } catch { /* private mode */ } };

const runningStandalone = () => window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
const usingIos = () => /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

// The install guide is one pop-up used everywhere: it opens by itself for a visitor who
// has never installed the app, and again from the settings row whenever it is asked for.
const INSTALL_GUIDE_SEEN_KEY = 'alum-install-guide-seen';

function installBenefits() {
  return ['سریع‌تر از مرورگر باز می‌شود', 'تمام‌صفحه، بدون نوار آدرس', 'بدون اینترنت هم کار می‌کند', 'اعلان نسخهٔ جدید می‌گیرد'];
}
function installSteps() {
  return usingIos()
    ? ['اپ را در مرورگر Safari باز کن.', 'دکمهٔ اشتراک‌گذاری (مربع با فلش رو به بالا) را بزن.', 'گزینهٔ «افزودن به صفحهٔ اصلی» را انتخاب کن.', 'نام «آلوم متال» را تأیید کن.']
    : ['اپ را در مرورگر Chrome یا Edge باز کن.', 'منوی مرورگر (سه‌نقطه) را باز کن.', 'گزینهٔ «نصب برنامه» یا «افزودن به صفحهٔ اصلی» را بزن.', 'تأیید کن تا آیکون اپ روی صفحهٔ اصلی بیاید.'];
}
function installGuideHtml() {
  const benefits = installBenefits().map((text) => `<li>${text}</li>`).join('');
  const steps = installSteps().map((text) => `<li>${text}</li>`).join('');
  const platform = usingIos() ? 'در iPhone و iPad' : 'در اندروید و کامپیوتر';
  const ctaLabel = 'نصب اپ';
  const note = 'نصب روی اندروید و iOS به آدرس https نیاز دارد؛ روی کامپیوتر هم می‌شود اپ را نصب کرد.';
  const cta = deferredInstallPrompt ? `<button class="primary-button install-guide-cta" id="installGuideCta" type="button">${ctaLabel}</button>` : '';
  return `<ul class="install-benefits">${benefits}</ul>${cta}<strong class="install-steps-title">${platform}</strong><ol class="install-steps">${steps}</ol><p class="guide-note">${note}</p>`;
}
function openInstallGuide() {
  openGuide('افزودن اپ به صفحه اصلی', installGuideHtml());
  setLocalFlag(INSTALL_GUIDE_SEEN_KEY);
}
// First visit and no app installed: the guide introduces itself once, a moment after the
// home screen is up. A pending update notice always has priority over it.
function maybeShowInstallGuide() {
  if (appIsInstalled() || localFlag(INSTALL_GUIDE_SEEN_KEY)) return;
  window.setTimeout(() => {
    if (appIsInstalled() || localFlag(INSTALL_GUIDE_SEEN_KEY)) return;
    if (previewDialog.open || $('#updateDialog')?.open || pendingUpdate) return;
    openInstallGuide();
  }, 1800);
}
// "Installed" is true while the app runs standalone, once the browser reported the
// installation, or once the platform told us the app is already installed. The
// detection below can only ever hide the banner, never bring it back.
let installedDetected = false;
const appIsInstalled = () => runningStandalone() || installedDetected || localFlag(INSTALLED_KEY);

async function detectInstalledApp() {
  if (!navigator.getInstalledRelatedApps) return;
  try {
    const related = await navigator.getInstalledRelatedApps();
    if (Array.isArray(related) && related.length) {
      installedDetected = true;
      setLocalFlag(INSTALLED_KEY);
      setInstallState();
    }
  } catch { /* unsupported or blocked; keep the current state */ }
}

function setInstallState() {
  const installed = appIsInstalled();
  const banner = $('#installBanner');
  if (banner) banner.hidden = installed || sessionFlag(INSTALL_DISMISS_KEY);
  const hint = $('#installBannerHint');
  if (hint) hint.textContent = deferredInstallPrompt ? 'یک ضربه برای نصب؛ بدون گشتن در تنظیمات مرورگر.' : 'آموزش گام‌به‌گام نصب روی صفحه اصلی را ببین.';
  const go = $('#installGo');
  if (go) go.textContent = deferredInstallPrompt ? 'نصب' : 'آموزش نصب';
  const row = $('#installButton');
  if (row) row.hidden = installed;
  const status = $('#installStatus');
  if (status) status.textContent = deferredInstallPrompt ? 'نصب سریع' : 'راهنمای نصب';
}
// The native prompt is only available when the browser offered one; the guide is the
// fallback for iOS (which never offers it) and for every browser that hides the menu entry.
function runInstallPrompt() {
  const prompt = deferredInstallPrompt;
  if (!prompt) return false;
  prompt.prompt();
  prompt.userChoice.then(() => { deferredInstallPrompt = null; setInstallState(); }).catch(() => setInstallState());
  return true;
}
function startInstallFlow() {
  if (runInstallPrompt()) return;
  openInstallGuide();
}
$('#previewBody').addEventListener('click', (event) => {
  if (!event.target.closest('#installGuideCta')) return;
  previewDialog.close();
  runInstallPrompt();
});
window.addEventListener('beforeinstallprompt', (event) => {
  event.preventDefault();
  deferredInstallPrompt = event;
  setInstallState();
});
window.addEventListener('appinstalled', () => {
  deferredInstallPrompt = null;
  installedDetected = true;
  setLocalFlag(INSTALLED_KEY);
  clearSessionFlag(INSTALL_DISMISS_KEY);
  if (previewDialog.open) previewDialog.close();
  showToast('اپ آلوم متال روی صفحه اصلی نصب شد');
  setInstallState();
});
$('#installGo')?.addEventListener('click', startInstallFlow);
$('#installButton')?.addEventListener('click', startInstallFlow);
$('#installDismiss')?.addEventListener('click', () => { setSessionFlag(INSTALL_DISMISS_KEY); setInstallState(); });
setInstallState();
detectInstalledApp();
maybeShowInstallGuide();

/* ==========================================================================
   Layer: sharing the app
   The native share sheet is used whenever the browser offers one (phones);
   every other case falls back to a pop-up with the direct link and a QR code.
   ========================================================================== */

const SHARE_URL = 'https://app-alummetal.ir/';

function legacyCopy(text) {
  try {
    const area = document.createElement('textarea');
    area.value = text;
    area.setAttribute('readonly', '');
    area.style.position = 'fixed';
    area.style.opacity = '0';
    document.body.appendChild(area);
    area.select();
    const ok = document.execCommand('copy');
    area.remove();
    return ok;
  } catch { return false; }
}
function copyText(text) {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    return navigator.clipboard.writeText(text).then(() => true).catch(() => legacyCopy(text));
  }
  return Promise.resolve(legacyCopy(text));
}
function openShareDialog() {
  const html = `<div class="share-body">
    <img class="share-qr" src="img/qr-app.png" alt="کد QR اپ آلوم متال" width="168" height="168" />
    <p class="share-hint">با دوربین گوشی این کد را اسکن کن تا اپ باز شود.</p>
    <div class="share-url">${SHARE_URL}</div>
    <button class="primary-button install-guide-cta" id="shareCopy" type="button">کپی لینک</button>
  </div>`;
  openGuide('اشتراک‌گذاری اپ', html);
}
$('#shareButton')?.addEventListener('click', async () => {
  const data = {
    title: isEnglish() ? 'Alum Metal Arak' : 'آلوم متال آراک',
    text: isEnglish() ? 'Alum Metal Arak app: section weight calculator, product catalogue and alloy database' : 'اپ آلوم متال آراک؛ محاسبه وزن مقاطع، کاتالوگ محصولات و بانک آلیاژها',
    url: SHARE_URL
  };
  // A cancelled share sheet is not an error: nothing is shown then.
  if (navigator.share) {
    try { await navigator.share(data); return; } catch (error) { if (error && error.name === 'AbortError') return; }
  }
  openShareDialog();
});
$('#previewBody').addEventListener('click', (event) => {
  if (!event.target.closest('#shareCopy')) return;
  copyText(SHARE_URL).then((ok) => showToast(ok ? 'لینک کپی شد.' : 'کپی انجام نشد؛ آدرس را دستی انتخاب کن.'));
});

const initialRoute = window.location.hash.slice(1) || 'home';
navigate(initialRoute);

/* ==========================================================================
   Layer: new-version alerts — currently switched OFF by the app owner
   (2026-10-22). Nothing asks for permission, no service worker is registered
   and no system notification is ever fired. The in-app update popup (below)
   still works, so the user is told about a new release inside the app.
   Do not re-enable notifications without asking the owner first.
   ========================================================================== */

const VERSION_KEY = 'alum-app-version';

// The settings row is disabled and only explains the current state.
function refreshNotifyUi() {
  const status = $('#notifyStatus');
  if (status) status.textContent = isEnglish() ? 'Not available right now' : 'فعلاً در دسترس نیست';
}

refreshNotifyUi();
// Whatever the removed daily-alert feature left behind is cleared once, so nothing can schedule again.
try { localStorage.removeItem('alum-notify-state-v1'); } catch { /* private mode */ }
try { sessionStorage.removeItem('alum-notify-dismissed'); } catch { /* private mode */ }
try { localStorage.removeItem('alum-notify-enabled'); } catch { /* private mode */ }
try { localStorage.removeItem('alum-update-notified'); } catch { /* private mode */ }

/* --------------------------------------------------------------- update flow */
const updateDialog = $('#updateDialog');
let pendingUpdate = null;

function setUpdateStatus(text) { const row = $('#updateStatus'); if (row) row.textContent = text; }

function openUpdateDialog() {
  if (!pendingUpdate || !updateDialog) return;
  const line = $('#updateVersionLine');
  if (line) line.textContent = pendingUpdate.date ? `نسخهٔ ${pendingUpdate.version} — تاریخ انتشار ${pendingUpdate.date}` : `نسخهٔ ${pendingUpdate.version}`;
  // version.json carries English notes next to the Persian ones, so the dialog can switch language.
  const notes = (isEnglish() && pendingUpdate.notesEn && pendingUpdate.notesEn.length ? pendingUpdate.notesEn : pendingUpdate.notes) || [];
  const list = $('#updateNotes');
  if (list) {
    list.innerHTML = notes.slice(0, 6).map((note) => `<li>${escapeLab(String(note))}</li>`).join('');
    list.hidden = !notes.length;
  }
  if (!updateDialog.open) { try { updateDialog.showModal(); } catch { /* already open */ } }
}

async function applyUpdate() {
  const target = pendingUpdate ? pendingUpdate.version : null;
  showToast('در حال به‌روزرسانی…');
  try { if ('caches' in window) { const keys = await caches.keys(); await Promise.all(keys.map((key) => caches.delete(key))); } } catch { /* ignore */ }
  // The old notification worker is deliberately NOT unregistered here: on some Android
  // launchers removing it made the installed app vanish from the home screen. The app no
  // longer registers it and never asks for notification permission, so it stays harmless.
  try { if (target) localStorage.setItem(VERSION_KEY, String(target)); } catch { /* ignore */ }
  if (target) {
    // The version query makes the browser fetch a fresh index.html (and with it the
    // versioned CSS/JS); the first lines of app.js strip that query again, so the
    // address bar only ever shows the domain itself.
    window.location.replace(`${window.location.pathname}?v=${encodeURIComponent(target)}`);
  } else {
    window.location.reload();
  }
}

async function checkForUpdate() {
  lastUpdateCheck = Date.now();
  try {
    const response = await fetch('version.json', { cache: 'no-store' });
    if (!response.ok) throw new Error('version unavailable');
    const data = await response.json();
    const remote = Number(data.version);
    if (!Number.isFinite(remote) || remote <= 0) throw new Error('bad version');
    let seen = Number(localStorage.getItem(VERSION_KEY) || 0) || 0;
    if (!seen) { try { localStorage.setItem(VERSION_KEY, String(remote)); } catch { /* ignore */ } setUpdateStatus('به‌روز'); return; }
    if (remote <= seen) { setUpdateStatus('به‌روز'); return; }
    pendingUpdate = { version: remote, date: data.date || '', notes: Array.isArray(data.notes) ? data.notes : [], notesEn: Array.isArray(data.notesEn) ? data.notesEn : [] };
    setUpdateStatus('نسخهٔ جدید دارد');
    // System notifications are switched off, so the in-app popup below is the only way
    // the visitor hears about a new release.
    let asked = false;
    try { asked = sessionStorage.getItem('alum-update-asked') === '1'; } catch { /* ignore */ }
    if (!asked) {
      try { sessionStorage.setItem('alum-update-asked', '1'); } catch { /* ignore */ }
      openUpdateDialog();
    }
  } catch {
    setUpdateStatus('بررسی هنگام اتصال');
  }
}

$('#updateApply')?.addEventListener('click', applyUpdate);
$('#updateLater')?.addEventListener('click', () => updateDialog?.close());
$('#updateClose')?.addEventListener('click', () => updateDialog?.close());
updateDialog?.addEventListener('click', (event) => { if (event.target === updateDialog) updateDialog.close(); });
$('#updateButton')?.addEventListener('click', async () => {
  if (pendingUpdate) { openUpdateDialog(); return; }
  setUpdateStatus('در حال بررسی…');
  await checkForUpdate();
  if (!pendingUpdate) showToast('نسخهٔ جدیدی موجود نیست؛ روی آخرین نسخه هستی.');
});
let lastUpdateCheck = 0;
checkForUpdate();
// A PWA can stay open for days, so re-check when the visitor returns to the tab
// (at most every ten minutes) instead of only on a fresh load.
document.addEventListener('visibilitychange', () => {
  if (document.hidden || Date.now() - lastUpdateCheck < 10 * 60 * 1000) return;
  checkForUpdate();
});
